using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PersonalCompanionTests
{
    internal static readonly EntityId Friend=new("created:friend");
    internal static WorldSession Start(bool policy=true){var lead=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:castle");var friend=lead with{Id=Friend.Value,Name="協力する浪人"};var setup=NewGameWorldTests.Setup([lead,friend],[]);return new(NewGameWorld.Create(setup.World,setup.Registered,lead.Id,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:policy?PersonalCompanions.Policy:null));}
    static CommandResult Act(WorldSession s,CompanionAction a,long amount=0,string? destination=null,string? id=null)=>s.ManageCompanion(new(new(id??"request:companion/"+s.Revision),Friend,a,amount,destination),s.PlayerControl,s.Revision);
    internal static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static void Agree(WorldSession s){var r=Act(s,CompanionAction.Agree,20);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    [Fact]public void RoninCanAgreeWithoutCreatingHouseServiceArmyOrTakingOtherPurse(){var s=Start();var w=s.DiagnosticSnapshot();Agree(s);var after=s.DiagnosticSnapshot();Assert.Equal(980,NewGameWork.Balance(after,s.PlayerControl));Assert.Equal(1020,NewGameWork.Balance(after,Friend));Assert.Equal(ContractJson.Write(w.Memberships),ContractJson.Write(after.Memberships));Assert.Equal(ContractJson.Write(w.ServiceBonds),ContractJson.Write(after.ServiceBonds));Assert.Empty(after.Units);Assert.True(s.CompanionView().Single(c=>c.Person==Friend).Active);}
    [Fact]public void DailyObligationPersistsAfterEndAndCannotBeDoublePaid(){var s=Start();Agree(s);Advance(s,86401);Assert.Equal(20,s.CompanionView().Single(c=>c.Person==Friend).Owed);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.EndAgreement).Code);Assert.Equal(20,s.CompanionView().Single(c=>c.Person==Friend).Owed);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Pay,20).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Pay,20).Code);Assert.Equal(960,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void UnpaidCompanionRefusesNewWorkWithoutRandomLoyaltyRoll(){var s=Start();Agree(s);Advance(s,86400);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Inspect).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Pay,20).Code);var r=Act(s,CompanionAction.Inspect);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    [Fact]public void DelegatedInspectionUsesCommonTaskAndPhysicalSealedReply(){var s=Start();Agree(s);var r=Act(s,CompanionAction.Inspect);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);Advance(s,8);var w=s.DiagnosticSnapshot();var q=w.Companions!.Orders.Single(q=>q.Input.Action==CompanionAction.Inspect);Assert.Equal(ExecutionPhase.Completed,w.Tasks.Single(t=>t.RequestId==q.Task!.RequestId).Execution);var paper=Assert.Single(w.Companions.Reports);Assert.Contains(new EntityId(paper.Message),w.SealedMessages);Assert.DoesNotContain(w.Messaging.Knowledge,k=>k.MessageId==paper.Message&&k.CharacterId==s.PlayerControl.Value);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(paper.Message),s.Revision).Code);}
    [Fact]public void CompanionsWalkActualRoadSeparatelyAndDoNotTeleportToLeader(){var s=Start();Agree(s);var r=Act(s,CompanionAction.TravelTogether,destination:"fork");Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);Advance(s,2);var w=s.DiagnosticSnapshot();Assert.Contains(w.Branches!.Journeys,j=>j.Actor==Friend);Assert.Equal(LocationKind.Traveling,w.Locations.Single(l=>l.Actor==s.PlayerControl).Kind);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.EndAgreement).Code);long at=w.Branches.Journeys.Max(j=>j.Legs[^1].EndAt);Advance(s,at);Assert.Equal(RegionalCampaign.Site("fork"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Friend).Site);Assert.True(s.CompanionView().Single(c=>c.Person==Friend).Nearby);Assert.Equal(2,s.DiagnosticSnapshot().Branches!.Journeys.Length);}
    [Fact]public void ContractAndTaskSaveDuringTravelContinuesWithSamePositionWalletAndKnownView(){var s=Start();Agree(s);Act(s,CompanionAction.TravelTogether,destination:"fork");Advance(s,3);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"companion-save-"+Guid.NewGuid().ToString("N")),w.Definitions);s.SetPaused(true);Assert.True(store.Save(s,"case",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));var b=host.Current;Export(s,b,"companion-travel");long end=w.Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);Advance(s,end);Advance(b,end);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.CompanionView()),ContractJson.Write(b.CompanionView()));s.SetPaused(true);Assert.True(store.Save(s,"arrival",w.WorldId).Published);var again=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,again.CommitLoad(store.Prepare("arrival"),again.Current,again.Current.Revision));Export(s,again.Current,"companion-arrival");}
    [Fact]public void RepeatedIdAndStaleViewDoNotChargeAgain(){var s=Start();var input=new CompanionInput(new("request:agreed"),Friend,CompanionAction.Agree,20);Assert.Equal(ResultCode.StateChanged,s.ManageCompanion(input,s.PlayerControl,999).Code);Assert.Equal(ResultCode.Accepted,s.ManageCompanion(input,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCompanion(input,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCompanion(input with{Amount=21},s.PlayerControl,s.Revision).Code);Assert.Equal(980,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ForeignHouseHeadAndWrongActorCannotBeRecruited(){var s=Start();var i=new CompanionInput(new("request:foreign"),new("person:nobunaga"),CompanionAction.Agree,20);Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(i,Friend,s.Revision).Code);}
    [Fact]public void OldNullPolicyRetainsBytesAndRejectsInjectedRoster(){var s=Start(false);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Companion",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Agree,20).Code);var w=s.DiagnosticSnapshot();w.Companions=new(1,PersonalCompanions.Policy,[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(19)][InlineData(21)][InlineData(-1)]public void AgreementRequiresExactDisclosedAdvance(long amount){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Agree,amount).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}

    [Fact]public void ExactDayEndDoesNotChargeAnotherDay(){var s=Start();Agree(s);Advance(s,86400);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.EndAgreement).Code);Assert.Equal(0,s.CompanionView().Single(c=>c.Person==Friend).Owed);Advance(s,172800);Assert.Equal(0,s.CompanionView().Single(c=>c.Person==Friend).Owed);}
    [Fact]public void RefusalDoesNotSpendOrCreateRoster(){var w=Start().DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Friend?c with{WillObey=false}:c).ToArray();var s=new WorldSession(w);var before=ContractJson.Write(w);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Agree,20).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void InsufficientPersonalMoneyKeepsUnpaidDebt(){var s=Start();Agree(s);Advance(s,49*86400);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Pay,980).Code);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Advance(s,50*86400);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Pay,20).Code);Assert.Equal(20,s.CompanionView().Single(c=>c.Person==Friend).Owed);Assert.Equal(2000,NewGameWork.Balance(s.DiagnosticSnapshot(),Friend));}
    [Fact]public void ForgedDurationAndIncompleteQueuedTaskCannotLoad(){var s=Start();Agree(s);Act(s,CompanionAction.TravelTogether,destination:"fork");var w=s.DiagnosticSnapshot();var q=w.Companions!.Orders.Last();w.Companions=w.Companions with{Orders=[w.Companions.Orders[0],q with{Task=q.Task! with{WorkSeconds=9999}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Requests=[];w.Tasks=[];w.Messaging=Start().DiagnosticSnapshot().Messaging;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ExistingDirectRetainerRemainsInOwnHouseAfterAgreement(){var setup=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var child=setup.People.Single(p=>p.Lord=="person:shingen");var s=new WorldSession(NewGameWorld.Create(setup,[],"person:shingen",historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy));var before=s.DiagnosticSnapshot();var r=s.ManageCompanion(new(new("request:own-retainer"),new(child.Id),CompanionAction.Agree,20),s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);Assert.Equal(ContractJson.Write(before.ServiceBonds),ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(s.DiagnosticSnapshot().Memberships));Assert.Equal("直属家臣との協力契約",s.CompanionView().Single(c=>c.Person.Value==child.Id).Kind);}
    [Fact]public void RoadOrderIdCannotBeReusedAsCompanionAgreement(){var s=Start();var move=TravelWorld.Move(s.DiagnosticSnapshot(),"request:travel","fork");Assert.Equal(ResultCode.Accepted,s.Submit(move,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,CompanionAction.Agree,20,id:"request:travel").Code);}
    [Fact]public void ProfilePinsPolicyWithoutReinterpretingOldProfiles(){var setup=Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"companion-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(setup.Start,setup.Registered,setup.Selected.Value,setup.Seed,inspectionPolicy:setup.InspectionPolicy,workPolicy:setup.WorkPolicy,companionPolicy:PersonalCompanions.Policy);Assert.Equal(PersonalCompanions.Policy,store.Read(p.Instance).CompanionPolicy);Assert.NotNull(NewCampaignStore.Build(p).Companions);}

    [Fact]public void RemoteInspectionCompletionRemainsAwaitingReportUntilReunion(){var s=Start();Agree(s);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Inspect).Code);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leader-away","fork"),s.Revision).Code);Advance(s,10);var w=s.DiagnosticSnapshot();Assert.Equal(ExecutionPhase.Completed,w.Tasks.Single(t=>t.Executor==Friend).Execution);Assert.Empty(w.Companions!.Reports);Assert.True(s.CompanionView().Single(c=>c.Person==Friend).Busy);Assert.False(s.CompanionView().Single(c=>c.Person==Friend).Nearby);}

    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var item in new[]{(s:a,tag:"before"),(s:b,tag:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+item.tag+".json"),ContractJson.Write(item.s.DiagnosticSnapshot()));}
    [Fact]public void FailedLeaderTaskRollsBackAcceptedCompanionTaskAndAgreementOrderAtomically()
    {
        var s=Start();var input=new CompanionInput(new("request:atomic-together"),Friend,CompanionAction.TravelTogether,0,"fork");string occupied="request:companion-leader/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(input.Id.Value));Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),occupied,"fork"),s.Revision).Code);Advance(s,1);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:atomic-back","castle"),s.Revision).Code);Advance(s,s.Seconds+1);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);Agree(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(input,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.DoesNotContain(s.DiagnosticSnapshot().Requests,r=>r.Intent.Actor==Friend);
    }

    [Fact]public void CompanionPrivatePayAndOwnMilitaryCustodyCoexistWithoutChangingTroopsOrPastFunds()
    {
        var friend=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:castle") with{Id=Friend.Value};var setup=NewGameWorldTests.Setup([friend],[]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"person:nobunaga",inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,companionPolicy:PersonalCompanions.Policy));Agree(s);
        void Send(NewMilitaryAction action){var input=new NewMilitaryInput(new("request:companion-military/"+s.Revision),action){AuthorityPolicy=action==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=action==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null};var r=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
        void Open(){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
        Send(NewMilitaryAction.Request);Advance(s,2);Open();Send(NewMilitaryAction.Accept);Advance(s,4);Open();Send(NewMilitaryAction.Pickup);Advance(s,86401);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Pay,20).Code);var w=s.DiagnosticSnapshot();Assert.Equal(960,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(100,w.Units.Sum(u=>u.Soldiers));Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w))).DiagnosticSnapshot()));
    }
}
